import{_ as r,L as i,o as n,a as s,a7 as o,h as u}from"./chunks/framework.B-LquxkF.js";const h=JSON.parse('{"title":"第 8 章 智能平台（UOS AI 智能办公生态）","description":"","frontmatter":{},"headers":[],"relativePath":"ch08_intelligent_platform.md","filePath":"ch08_intelligent_platform.md"}'),g={name:"ch08_intelligent_platform.md"};function e(q,t,p,a,d,c){const l=i("Layer");return n(),s("div",null,[t[0]||(t[0]=o('<h1 id="第-8-章-智能平台-uos-ai-智能办公生态" tabindex="-1">第 8 章 智能平台（UOS AI 智能办公生态） <a class="header-anchor" href="#第-8-章-智能平台-uos-ai-智能办公生态" aria-label="Permalink to &quot;第 8 章 智能平台（UOS AI 智能办公生态）&quot;">​</a></h1><blockquote><p><strong>本章主线：用&quot;搭建一座智能平台&quot;的顺序，把 5 张图串成一个体系。</strong></p><p>一个智能平台不是功能堆砌，而是<strong>分层长出来的</strong>。它由四层构成，彼此是承接关系：</p><table tabindex="0"><thead><tr><th>层</th><th>回答什么</th><th>承载章节</th></tr></thead><tbody><tr><td><strong>底座</strong> 顶起全局的骨架</td><td>智能体能力如何被平台化组织</td><td>8.5 Agent OS 分层架构</td></tr><tr><td><strong>血肉</strong> 接入海量外部能力</td><td>应用/技能/AI 能力如何进来</td><td>8.3 智能生态（MCP / Skills / SDK）</td></tr><tr><td><strong>功能</strong> 长成用户可用的能力</td><td>进来的能力如何变成&quot;能写、能办&quot;</td><td>8.1 智能写作、8.2 智能办公</td></tr><tr><td><strong>触达</strong> 把能力送达到人手中</td><td>能力如何在跨端场景被调用</td><td>8.4 智能协同 Uclaw</td></tr></tbody></table><p>四层的关系一句话：<strong>底座（Agent OS）决定&quot;能力在哪儿被组织&quot;，生态（MCP/Skills/SDK）决定&quot;能力从哪儿来&quot;，功能（写作/办公）决定&quot;能力被用来干什么&quot;，触达（Uclaw）决定&quot;人在哪里用&quot;。</strong></p><p>全章重点回答&quot;<strong>是如何实现的、如何构建的</strong>&quot;，并联动第 2 章 UOS 系统能力、第 3 章系统软件、第 4 章智能体技术、第 7 章 MCP 实践。</p><p>来源：统信软件智能平台产品方案（2026 第三届教育信息技术应用创新大赛），是国产操作系统 AI+ 生态的落地形态。</p></blockquote><h2 id="_8-1-智能写作" tabindex="-1">8.1 智能写作 <a class="header-anchor" href="#_8-1-智能写作" aria-label="Permalink to &quot;8.1 智能写作&quot;">​</a></h2><blockquote><p>本节解决：AI 写文章如何做到&quot;内容可信、每句有据、数据不出门&quot;。</p><p><strong>层定位</strong>：功能层——能力长出来后最基本的落地形态（&quot;写&quot;这件事）。</p></blockquote><ul><li><strong>定位</strong>：基于本地素材权威成文，确保内容真实可信可溯</li><li><strong>一键投喂</strong>：基于本地素材与大纲成文，每一句话都踩在需求点上——不是凭空生成，而是先把本地资料&quot;喂&quot;给模型，再按照大纲逐段成文</li><li><strong>在线修改</strong>：集成编辑器，可对大纲、正文在线&quot;整容&quot;（调整结构、改写语句），写、改一个界面完成</li><li><strong>安全可控</strong>：支持本地 / 私有模型生成，数据&quot;不出门&quot;——素材与生成内容不离开本机或私有环境</li><li><strong>有据可查</strong>：生成内容标注参考来源，专业且严谨——每段可追溯来自哪份素材</li></ul><p><strong>如何实现 / 构建</strong>：</p><ul><li><p>关键是&quot;本地素材前置到模型之前&quot;：先做文档导入与解析，把素材切段、用 Embedding 转成向量（RAG 检索增强，联动 ch04 §4.10）；成文时按大纲逐段检索相关素材并引用</p></li><li><p>用本地 / 私有化模型推理（数据不出域，联动 ch04 §4.18 推理服务），实现&quot;安全可控&quot;</p></li><li><p>生成时对每个关键句挂&quot;来源引用&quot;，实现&quot;有据可查&quot;</p></li><li><p>一句话总结：<strong>素材进 → 检索定位 → 按大纲成文 → 标注来源 → 本地模型生成</strong>，五步闭环。</p></li><li><p>衔接：写作是&quot;单点&quot;能力；跨出文档去调用别的应用时，需要&quot;任务拆解 + 工具协同&quot;——下一节讲智能办公。</p></li></ul><h2 id="_8-2-智能办公" tabindex="-1">8.2 智能办公 <a class="header-anchor" href="#_8-2-智能办公" aria-label="Permalink to &quot;8.2 智能办公&quot;">​</a></h2><blockquote><p>本节解决：怎样让一句自然语言，自动拆解成一串操作、由多个应用协同完成。</p><p><strong>层定位</strong>：功能层（进阶）——从&quot;写&quot;扩大到&quot;办&quot;，跨出文档、调用全局。</p></blockquote><ul><li><strong>定位</strong>：一句话完成跨应用、跨业务系统的复杂任务</li><li><strong>智能的任务拆解</strong>：UOS AI 具备强大的任务理解与拆解能力，能把用户意图自动分解为多个执行步骤，并协调系统工具与应用协同完成任务——让工作从&quot;多步操作&quot;升级为&quot;一句话完成&quot;</li><li><strong>全面的技能体系</strong>：支持 MCP 与 Skills 技能调用机制，可根据任务目标智能组合或自动生成新技能，持续扩展能力边界，满足多样化办公需求</li><li><strong>广泛的业务场景</strong>：一键下载视频、一键合并 PDF、一键总结邮件……</li></ul><p><strong>如何实现 / 构建</strong>：</p><ul><li><p>核心是&quot;<strong>意图 → 目标 → 步骤</strong>&quot;的规划与工具协同闭环：用户一句话 → LLM 解析意图 → 拆成多个可执行子步骤（Planning，联动 ch04 §4.4）→ 每步调用对应工具 / 应用（Function Calling / MCP，联动 ch04 §4.5 / 4.6）→ 汇总结果返回</p></li><li><p>能力扩展靠两套机制：<strong>MCP</strong>（接入第三方应用，解决&quot;怎么接&quot;）+ <strong>Skills</strong>（把高层任务封装成可复用好用的能力，联动 ch04 §4.7，解决&quot;怎么用&quot;）</p></li><li><p>&quot;一键合并 PDF&quot;这类预置场景 = 已把多个子步骤封装成可复用 Skill，用户只需一句话触发</p></li><li><p>一句话总结：<strong>会拆解（规划）+ 能调用（工具/MCP）+ 好复用（Skills 沉淀）</strong>，共同撑起&quot;一句话办成一件事&quot;。</p></li><li><p>衔接：要支撑这么多应用与技能的接入，底层需要丰富的外部生态——下一节讲智能生态（MCP / Skills / SDK）。</p></li></ul><h2 id="_8-3-智能生态-mcp-skills-sdk" tabindex="-1">8.3 智能生态（MCP / Skills / SDK） <a class="header-anchor" href="#_8-3-智能生态-mcp-skills-sdk" aria-label="Permalink to &quot;8.3 智能生态（MCP / Skills / SDK）&quot;">​</a></h2><blockquote><p>本节解决：智能平台靠什么把海量应用、技能、AI 能力&quot;灵活接入&quot;，打造企业专属智能助手。</p><p><strong>层定位</strong>：血肉层——决定&quot;能力从哪儿来&quot;，是平台与外部世界的接口。</p></blockquote><ul><li><strong>定位</strong>：灵活接入生态能力，打造企业专属智能助手。三大抓手：<strong>MCP（连通）、Skills（技能）、SDK（构建）</strong>。</li></ul><p><strong>MCP：连接更广泛</strong>——三方应用无缝接入，一键联动常用办公系统</p><ul><li>规模：word、excel、图表分析、12306 等 <strong>9000+</strong> MCP</li><li>机制：MCP 统一工具接口标准，Server 提供 Tool，Client（UOS AI）负责连接与调用（联动 ch04 §4.6 与第 7 章实践）</li></ul><p><strong>Skills：技能更全面</strong>——自动拆解任务，1.2W+ 技能智能调用 / 自建</p><ul><li>规模：<strong>1.2W+</strong> 常用 skills</li><li>机制：Skill 是封装好的高层任务能力，抽象层级高于单个底层 Tool；可按任务自动组合，也能自建（联动 ch04 §4.7）</li></ul><p><strong>SDK：AI 应用构建更简单</strong>——客户可灵活调用快速集成，基于现有系统快速构建 AI 应用</p><ul><li>规模：<strong>60+</strong> AI SDK，覆盖语音转文字、图像识别等</li><li>机制：把通用 AI 能力（语音、视觉、文本、知识库、模型管理）封装成 SDK 接口，开发者在现有系统里快速集成，不必从零搭建（对应 Agent OS 的 AI SDK 层）</li></ul><p><strong>如何构建</strong>：</p><ul><li><p>生态构建是&quot;<strong>三层递进</strong>&quot;：先定标准（MCP 统一工具接口）→ 再沉淀能力（Skills 把反复用到的任务封装）→ 再提供开发入口（SDK 让客户二次开发）</p></li><li><p>三者关系：<strong>MCP 解决&quot;怎么接&quot;，Skills 解决&quot;接进来怎么用得更顺&quot;，SDK 解决&quot;别人怎么基于它再开发&quot;</strong></p></li><li><p>规模背后的复用逻辑：9000+ MCP、1.2W+ Skill、60+ SDK，靠的是&quot;标准统一 + 生态开放&quot;——只要按标准注册，任何应用、技能、AI 能力都能被 UOS AI 调用。</p></li><li><p>衔接：能力丰富之后，还要解决&quot;人在哪里用、多端怎么同步、安全怎么控&quot;——下一节讲智能协同 Uclaw。</p></li></ul><h2 id="_8-4-智能协同-uclaw" tabindex="-1">8.4 智能协同 Uclaw <a class="header-anchor" href="#_8-4-智能协同-uclaw" aria-label="Permalink to &quot;8.4 智能协同 Uclaw&quot;">​</a></h2><blockquote><p>本节解决：手机与电脑如何跨端协同，远程操控与安全如何兼得。</p><p><strong>层定位</strong>：触达层——决定&quot;人在哪里用&quot;，把能力跨端送达到用户。</p></blockquote><ul><li><strong>定位</strong>：跨端无界，一屏掌控手机与电脑</li><li><strong>开箱即用</strong>：符合国内用户使用习惯，深度打通飞书、钉钉、QQ 等主流应用接口，一键部署即刻使用</li><li><strong>手机跨端操控</strong>：通过手机发送指令，AI 自动执行复杂操作，随时随地远程掌控系统</li><li><strong>高效节能</strong>：深度融合系统能力，通过&quot;工具直达执行路径&quot;，避免冗余推理，大幅降低计算消耗</li><li><strong>安全可控</strong>：基于 USEC 安全体系，实现权限精细化管控，确保系统稳定与用户数据安全</li></ul><p><strong>如何实现 / 构建</strong>：</p><ul><li><p>跨端协同靠&quot;<strong>同一套 AI 能力 + 端侧 / 云侧指令通道</strong>&quot;：手机发指令 → 端侧智能体理解 → 直接调用系统工具执行；不绕大模型做无谓推理，正是&quot;工具直达执行路径，避免冗余推理、降低计算消耗&quot;</p></li><li><p>&quot;深度打通飞书 / 钉钉 / QQ&quot;= 这些应用以 MCP / Skill 方式接入，一键部署即注册好连接（对应 8.3 生态）</p></li><li><p>安全靠 USEC 体系：权限精细化管控 + 数据不出域（联动 ch02 权限、ch04 §4.15 安全），与&quot;智能写作数据不出门&quot;一脉相承</p></li><li><p>一句话总结：<strong>端侧智能体 + 免冗余直达 + 权限管控</strong>，实现&quot;手机一句话、电脑自动办&quot;。</p></li><li><p>衔接：以上所有能力最终需要一个完整的平台来承载、调度——下一节看 Agent OS 如何分层把它们组织起来。</p></li></ul><h2 id="_8-5-agent-os-平台架构" tabindex="-1">8.5 Agent OS 平台架构 <a class="header-anchor" href="#_8-5-agent-os-平台架构" aria-label="Permalink to &quot;8.5 Agent OS 平台架构&quot;">​</a></h2><blockquote><p>本节解决：UOS AI 的智能能力如何被分层组织成可扩展的平台，每一层做什么、彼此如何协作。</p><p><strong>层定位</strong>：底座层——顶起整个平台的骨架，其余三层的&quot;承重墙&quot;。</p></blockquote><ul><li><strong>定位</strong>：<strong>Agent OS</strong>，是 UOS AI 把&quot;智能体能力&quot;系统化、平台化的分层架构。自下而上五层：<strong>模型调度层 → 系统能力层 → AI SDK → 智能体服务层 → 应用能力层</strong>。</li></ul>',31)),u(l,{data:'{"title":"Agent OS 五层（自下而上）","sequence":"bottom-up","layers":[{"title":"应用能力层","items":["写作智能体","数据分析","MCP/Skills 扩展"]},{"title":"智能体服务层","items":["多通道感知","运行时沙箱","记忆与个性化"]},{"title":"AI SDK","items":["语音/视觉/文本/知识库接口"]},{"title":"系统能力层","items":["RAG/文本/语音/图像服务","任务队列"]},{"title":"模型调度层","items":["统一运行时","统一 API 网关","混合路由"]}]}'}),t[1]||(t[1]=o('<p><strong>模型调度层</strong>：统一多种模型接入与路由</p><ul><li>统一运行时：llama.cpp / ONNXRuntime / OpenVINO——把不同推理引擎抽象成统一运行时（联动 ch04 §4.18）</li><li>统一 API 网关：DeepSeek / Kimi / GLM / QWen、GPT / Claude / 自定义接口——对外统一接口，屏蔽各模型差异</li><li>混合路由引擎：端侧模型 / 云侧模型 / 私有化部署模型，按场景自动选择</li></ul><p><strong>系统能力层</strong>：把系统级能力沉淀为通用服务</p><ul><li>系统业务管理：RAG 服务、文本服务、语音服务、图像服务</li><li>模型任务管理：任务队列、会话管理</li><li>系统调度管理：模型路由、模型配置</li></ul><p><strong>AI SDK</strong>：面向开发者提供通用 AI 能力接口</p><ul><li>语音接口、视觉接口、文本接口、知识库接口、模型管理接口——对应智能生态&quot;60+ AI SDK&quot;的规范化形态</li></ul><p><strong>智能体服务层</strong>：让智能体&quot;能感知、能安全运行、有记忆&quot;</p><ul><li>全局场景感知：语义感知 / 屏幕感知 / 语音感知、用户交互感知 / 系统事件感知 / 外设网络设备感知</li><li>运行沙箱环境：智能体行为识别、运行时沙箱（安全隔离，联动 ch04 §4.15）</li><li>记忆与个性化：分层记忆 / 记忆管理、用户画像 / 个性化交互（联动 ch04 §4.9）</li></ul><p><strong>应用能力层</strong>：面向用户的具体能力</p><ul><li>通用智能体能力：智能体管理 / 推理核心 / 智能体编排与路由</li><li>办公与生产力：UOS AI 通用智能体、写作智能体、数据分析（对应 8.1 / 8.2）</li><li>伴随式 AI 助手：7×24 待命 / 记忆系统、友好交互 / 强大的能力</li><li>三方扩展：智能体插件 / MCP / Skills（对应 8.3 生态接入）</li></ul><p><strong>如何构建 / 组织</strong>：</p><ul><li>分层原则：<strong>下层提供通用能力，上层组合成业务能力</strong>——模型调度层屏蔽&quot;跑什么模型&quot;，系统能力层把 RAG / 文本 / 语音做成通用服务，AI SDK 给开发者统一入口，智能体服务层赋予&quot;感知 + 安全 + 记忆&quot;，应用能力层才面向用户</li><li>横向贯穿条：<strong>AI SDK</strong> 是横切层，给各层与外部提供一体化接口</li><li>分层价值：接入新模型、新增应用、扩展技能都不必改动上层——<strong>生态可插拔、能力可演进</strong></li><li>一句话总结：<strong>五层分工 + AI SDK 横切</strong>，把分散的智能体能力组织成一个可持续扩展的操作系统级平台。</li></ul><blockquote><p><strong>全章串联：一座智能平台是&quot;长&quot;出来的，不是&quot;堆&quot;出来的。</strong></p><p><strong>构建链路（自下而上）</strong>：</p><ol><li>先立<strong>底座</strong>——Agent OS 把智能体能力分五层组织（8.5），决定&quot;能力在哪儿被组织&quot;；</li><li>再通<strong>血肉</strong>——用 MCP / Skills / SDK 接进海量外部应用、技能与 AI 能力（8.3），决定&quot;能力从哪儿来&quot;；</li><li>后长<strong>功能</strong>——把这些能力打包成&quot;能写、能办&quot;的用户应用（8.1 写作、8.2 办公），决定&quot;能力用来干什么&quot;；</li><li>终达<strong>用户</strong>——靠 Uclaw 跨端触达（8.4），决定&quot;人在哪里用&quot;。</li></ol><p><strong>与手册既有章节的知识映射</strong>：</p><table tabindex="0"><thead><tr><th>平台层</th><th>对应手册既有知识</th></tr></thead><tbody><tr><td>模型调度层</td><td>ch04 §4.18 推理服务（统一运行时、API 网关、混合路由）</td></tr><tr><td>系统能力层</td><td>ch04 §4.10 RAG、ch02 / ch03 系统与系统软件能力</td></tr><tr><td>AI SDK</td><td>ch04 能力的标准化出口（开发者集成）</td></tr><tr><td>智能体服务层</td><td>ch04 §4.9 记忆、§4.15 安全（沙箱）、4.3 多通道感知</td></tr><tr><td>应用能力层 / 功能</td><td>ch04 §4.4 规划、§4.5–4.7 工具/MCP/Skill、§4.14 多智能体</td></tr><tr><td>触达 Uclaw</td><td>ch04 §4.16 效率（免冗余推理）、ch02 权限、§4.15 安全</td></tr></tbody></table><p><strong>一句话落点</strong>：整个 UOS AI 智能平台 = <strong>智能体技术（ch04）+ 系统能力（ch02 / ch03）+ 开放生态（MCP / Skills / SDK）</strong> 在国产操作系统上的成体系落地。</p></blockquote>',13))])}const A=r(g,[["render",e]]);export{h as __pageData,A as default};
